int process_query_result(const char* query_result, size_t result_len, char* output_buffer, size_t buffer_size) {
    // 检查输入参数的有效性
    if (query_result == NULL || output_buffer == NULL) {
        return -1; // 参数错误
    }

    // 检查缓冲区大小是否足够
    if (buffer_size == 0) {
        return -2; // 缓冲区大小为0
    }

    // 如果查询结果长度为0，直接返回
    if (result_len == 0) {
        output_buffer[0] = '\0'; // 设置空字符串
        return 0;
    }

    // 检查是否需要截断数据以适应缓冲区
    size_t copy_len = result_len;
    if (result_len >= buffer_size) {
        // 缓冲区不够大，需要截断数据，并确保字符串以null结尾
        copy_len = buffer_size - 1;
    }

    // 使用memcpy将查询结果复制到输出缓冲区
    memcpy(output_buffer, query_result, copy_len);

    // 如果数据被截断，确保缓冲区以null结尾
    if (copy_len < result_len) {
        output_buffer[copy_len] = '\0';
        return -3; // 数据被截断
    } else {
        // 如果复制的数据长度小于缓冲区大小，确保以null结尾
        if (copy_len < buffer_size) {
            output_buffer[copy_len] = '\0';
        }
        return copy_len; // 返回实际复制的字节数
    }
}
